def create_testing_env(tl: TestLine, output_dir_path: str) -> TestingEnv:
    """
    Creates testing environment which contains tested BTS(s) and set of common testing tools.
    :param tl: configuration of Testline from init file which will be used during tests
    :param output_dir_path: absolute path to directory where all artifacts from test execution (i.e. logs, SCFs, SW packages) will be stored
    :returns: testing environment containing prepared BTS(s) and testing tools
    :raises UnsupportedBtsType: when type of any BTS configuration from provided Testline configuration is unsupported
    """
    testing_env = TestingEnv(gnbs=[],
                             enbs=[],
                             caller=CallManager(),
                             stopwatch=Stopwatch(),
                             errors=ErrorHistory(),
                             output_dir_path=output_dir_path,
                             log_collector=LogCollector(),
                             variables=EnvVariables())

    if tl.gnbs:
        testing_env.gnbs = [create_bts(bts_config=gnb_config) for gnb_config in tl.gnbs]

    if tl.enbs:
        testing_env.enbs = [create_bts(bts_config=enb_config) for enb_config in tl.enbs]

    return testing_env


def update_testing_env(testing_env: TestingEnv,
                       tl: TestLine):
    """
    Updates testing environment with adjusted BTS components from provided TestLine configuration (mainly custom tl).
    :param testing_env: testing environment which contains tested BTS(s) and testing tools
    :param tl: configuration of Testline from init file which will be used during tests
    """
    testing_env.gnbs, testing_env.enbs = [], []

    if tl.gnbs:
        testing_env.gnbs = [create_bts(bts_config=gnb_config) for gnb_config in tl.gnbs]

    if tl.enbs:
        testing_env.enbs = [create_bts(bts_config=enb_config) for enb_config in tl.enbs]


def prepare_testing_env(testing_env: TestingEnv,
                        tl: TestLine,
                        cus_scf_paths: Dict[str, str] = None,
                        dus_scf_paths: Dict[str, str] = None,
                        check_bts_state: bool = True,
                        ues: List[UE] = None,
                        ue_reboot: bool = False,
                        ue_network_modes: Dict[str, str] = None):
    """
    Prepares testing environment before the test.
    Executes following test pre-conditions:
        * start background log collection (i.e. syslog, RMOD serial logs)
        * open all API connections
        * load components of all BTSs
        * (optional) commission specified CUs
        * (optional) commission specified DUs
        * check whether all BTS components are detected accordingly to configuration from init
        * start watching alarms
        * (optional) check whether state of all BTS components is as expected
    :param testing_env: testing environment which contains tested BTS(s) and testing tools
    :param tl: configuration of Testline from init file which will be used during test
    :param cus_scf_paths: dictionary with absolute paths to SCF files which will be used for commissioning of each CU (specified by its name);
                          if DU is omitted in the dictionary, it will not be commissioned;
                          i.e. {'CU_8463': '/home/ute/scfs/MRBTS-8463/CU_8463.xml'}
                          defaults to None (CUs will not be commissioned at all)
    :param dus_scf_paths: dictionary with absolute paths to SCF files which will be used for commissioning of each DU (specified by its name);
                          if DU is omitted in the dictionary, it will not be commissioned;
                          i.e. {'NRDU-1': '/home/ute/scfs/nrdu_1_scf.xml',
                                'NRDU-2': '/home/ute/scfs/nrdu_2_scf.xml'}
    :param check_bts_state: defines whether current state of BTS(s) should be checked against
                            standard state expected before starting the test;
                            defaults to True
    :param ues: configurations of UEs from init file which will be used during test execution;
                defaults to None (no UEs will be used, L3 call will not be executed during test)
    :param ue_reboot: defines whether UEs should be rebooted before test execution;
                      defaults to False (UEs will not be rebooted)
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             defaults to None (network mode will not be changed on any UE)
    :raises ResultError: when detected components of any BTS will not match its expected components from provided
                         configuration or any component will not be in expected state during BTS state check
    """
    testing_env.log_collector.start_logs_collection()

    for gnb_id, gnb in enumerate(testing_env.gnbs):
        _prepare_bts(gnb, tl.gnbs[gnb_id], cus_scf_paths, dus_scf_paths, check_bts_state, testing_env.errors,
                     testing_env.output_dir_path)

    for enb_id, enb in enumerate(testing_env.enbs):
        _prepare_bts(enb, tl.enbs[enb_id], cus_scf_paths, dus_scf_paths, check_bts_state, testing_env.errors,
                     testing_env.output_dir_path)

    if ues:
        testing_env.caller.configure_ues(ues=ues,
                                         reboot=ue_reboot,
                                         ue_network_modes=ue_network_modes)


def cleanup_testing_env(testing_env: TestingEnv, test_result: str):
    """
    Cleans up testing environment after the test.
    Executes following test post-conditions:
        * collect all requested logs
        * stop watching alarms
        * check whether no unexpected alarms were detected during test execution
        * checks whether no error occurred during test teardown phase
    :param testing_env: testing environment which contains tested BTS(s) and testing tools
    :param test_result: result of test execution; can be 'PASS' or 'FAIL'
    :raises ResultError: if any disallowed alarm was detected during test execution
    """
    errors = testing_env.errors
    testing_env.log_collector.collect_logs(test_result=test_result, errors=errors)

    for bts in testing_env.btss:
        _collect_detected_alarms_and_stop_watching_them(bts.cus, errors)
        _collect_detected_alarms_and_stop_watching_them(bts.dus, errors)
        try:
            bts.disconnect()
        except ApiException:
            pass

    testing_env.caller.clean_up_env()
    errors.check()


@pretty_log
def save_initial_configs(testing_env: TestingEnv) -> Dict[str, Dict[str, Dict[str, str]]]:
    """
    Saves initial SCF configuration of BTSs in test execution directory.
    :param testing_env: testing environment which contains tested BTS(s) and testing tools
    :returns: dictionary with paths to saved SCF files for each BTS, i.e.:
              {'CloudBts_8463': {'cus': {'CU_8463': '/home/ute/Desktop/result/CloudBts_8463/CU_8463.xml'},
                                 'dus': {'NRDU-1': '/home/ute/Desktop/result/CloudBts_8463/CU_8463_NRDU-1.xml'}}}
    """
    tl_configs = {}
    for bts in testing_env.btss:
        tl_configs[bts.name] = _save_config(bts, testing_env.output_dir_path)

    return tl_configs


@pretty_log
def restore_initial_configs(testing_env: TestingEnv,
                            config_info: Dict[str, Dict[str, Dict[str, str]]]):
    """
    Restores initial SCF configuration of BTSs.
    :param testing_env: testing environment which contains tested BTS(s) and testing tools
    :param config_info: dictionary with paths to saved SCF files for each BTS, i.e.:
                        {'CloudBts_8463': {'cus': {'CU_8463': '/home/ute/Desktop/result/CloudBts_8463/CU_8463.xml'},
                                           'dus': {'NRDU-1': '/home/ute/Desktop/result/CloudBts_8463/NRDU-1.xml'}}}
    """
    for bts in testing_env.btss:
        bts_config = config_info[bts.name]

        cus_scf_paths = bts_config['cus']
        dus_scf_paths = bts_config['dus']
        _recommission(bts, cus_scf_paths, dus_scf_paths)


def _prepare_bts(bts: CloudBts,
                 bts_config: Union[gNB, Enb],
                 cus_scf_paths: Dict[str, str],
                 dus_scf_paths: Dict[str, str],
                 check_state: bool,
                 errors: ErrorHistory,
                 output_dir_path: str):
    bts.connect()
    _commission(bts, bts_config, cus_scf_paths, dus_scf_paths, output_dir_path, errors)
    _start_watching_alarms(bts, bts_config, output_dir_path)

    if dus_scf_paths or cus_scf_paths:
        _recommission(bts, cus_scf_paths, dus_scf_paths)
    _check_detected_bts_components(bts, bts_config, errors)

    if check_state:
        _check_bts_components_state(bts, errors)


@pretty_log
def _start_watching_alarms(bts: CloudBts, bts_config: Union[gNB, Enb], log_dir: str):
    interval = 1.0

    for cu_id, cu in enumerate(bts.cus):
        cu.alarms_watchdog.watch_alarms(bts_config=bts_config,
                                        cu_id=cu_id,
                                        allowed_alarms=allowed_cu_alarms,
                                        interval=interval,
                                        log_dir=log_dir)

        for du_id, du in enumerate(cu.dus):
            du.alarms_watchdog.watch_alarms(bts_config=bts_config,
                                            cu_id=cu_id,
                                            du_id=du_id,
                                            allowed_alarms=allowed_du_alarms,
                                            interval=interval,
                                            log_dir=log_dir)


@pretty_log
def _commission(bts: CloudBts, bts_config: Union[gNB, Enb], cus_scf_paths: Dict[str, str],
                dus_scf_paths: Dict[str, str], log_dir: str, errors: ErrorHistory):
    alarms_watchdog_interval = 1.0
    cu_id = 1
    scfs_counter = ((len(cus_scf_paths) if cus_scf_paths is not None else 0)
                    + (len(dus_scf_paths) if dus_scf_paths is not None else 0))
    alarms_watchdogs = []

    try:
        if bts.is_cu_uncommissioned():
            cu_name = f'CU_{bts_config.cu.instance_id}'

            if cu_name in cus_scf_paths:
                cu_alarms_watchdog = alarms_watchdog()
                cu_alarms_watchdog.watch_alarms(bts_config=bts_config,
                                                cu_id=cu_id,
                                                allowed_alarms=allowed_cu_alarms,
                                                interval=alarms_watchdog_interval,
                                                log_dir=log_dir)
                alarms_watchdogs.append(cu_alarms_watchdog)
                cu_alarms_watchdog.allow_alarm(fault_id='4592')
                cu_alarms_watchdog.allow_alarm(fault_id='7104')

                bts.commission_cu(scf_path=cus_scf_paths[cu_name])
                del cus_scf_paths[cu_name]
            else:
                errors.add(error_type='Missing mandatory SCF file',
                           error_msg=f'SCF file is not provided for uncommissioned {cu_name}. '
                                     f'Please add SCF file path to "cus_scf_paths" dictionary during Cloud Suite Setup')

        for du_id in range(len(bts_config.dus)):
            if bts.is_du_uncommissioned(du_id + 1):
                du_name = f'NRDU-{du_id + 1}'

                if du_name in dus_scf_paths:
                    du_alarms_watchdog = alarms_watchdog()
                    du_alarms_watchdog.watch_alarms(bts_config=bts_config,
                                                    cu_id=cu_id,
                                                    du_id=du_id,
                                                    allowed_alarms=allowed_du_alarms,
                                                    interval=alarms_watchdog_interval,
                                                    log_dir=log_dir)
                    alarms_watchdogs.append(du_alarms_watchdog)
                    du_alarms_watchdog.allow_alarm(fault_id='4592')

                    bts.commission_du(scf_path=dus_scf_paths[du_name],
                                      du_id=du_id + 1)
                    del dus_scf_paths[du_name]
                else:
                    errors.add(error_type='Missing mandatory SCF file',
                               error_msg=f'SCF file is not provided for uncommissioned {du_name}. Please add '
                                         f'SCF file path to "dus_scf_paths" dictionary during Cloud Suite Setup')

        scfs_counter_after_commissioning = ((len(cus_scf_paths) if cus_scf_paths is not None else 0)
                                            + (len(dus_scf_paths) if dus_scf_paths is not None else 0))
        if scfs_counter_after_commissioning != scfs_counter:
            bts.check_if_reachable(delay=60)
            sleep(300)  # Waiting for bts ready to be loaded after first commissioning

        bts.load()

        if scfs_counter_after_commissioning != scfs_counter:
            for cu in bts.cus:
                for du in cu.dus:
                    du.check_if_pods_are_running(timeout=180, silent=True)
                    du.check_state(state='on_air', timeout=360, silent=True)

            bts.cells.check_state_on_all(state='online',
                                         timeout=60)

    finally:
        if alarms_watchdogs:
            _collect_detected_alarms_during_commissioning_and_stop_watching_them(alarms_watchdogs, errors)


@pretty_log
def _recommission(bts: CloudBts, cus_scf_paths: Dict[str, str], dus_scf_paths: Dict[str, str]):
    is_recommissioned = False
    for cu in bts.cus:
        if cus_scf_paths:
            if cu.name in cus_scf_paths:
                for du in cu.dus:
                    du.allow_alarm(fault_id='7504')

                cu.allow_alarm(fault_id='4592')
                cu.config.recommission(scf_path=cus_scf_paths[cu.name])
                cu.check_if_reachable(delay=60, timeout=240)
                is_recommissioned = True

                is_du_for_recommissioning = any(du.name in dus_scf_paths for du in cu.dus) if dus_scf_paths else False
                if not is_du_for_recommissioning:
                    for du in cu.dus:
                        du.check_state(state='on_air', timeout=360)
            else:
                log_info(f'Path to SCF file for {cu.name} was not specified, {cu.name} will not be recommissioned')

        if dus_scf_paths:
            for du in cu.dus:
                if du.name in dus_scf_paths:
                    du.cu.allow_alarm(fault_id='7104')
                    du.allow_alarm(fault_id='4592')

                    du.config.recommission(scf_path=dus_scf_paths[du.name])
                    du.check_if_reachable(delay=60, timeout=240)
                    du.check_if_pods_are_running(timeout=180)
                    du.check_state(state='on_air', timeout=360)
                    is_recommissioned = True

                    du.cu.disallow_alarm(fault_id='7104')
                    du.disallow_alarm(fault_id='4592')
                else:
                    log_info(f'Path to SCF file for {du.name} was not specified, {du.name} will not be recommissioned')

        if cus_scf_paths and cu.name in cus_scf_paths:
            for du in cu.dus:
                du.disallow_alarm(fault_id='7504')
            cu.disallow_alarm(fault_id='4592')

    bts.load()

    if is_recommissioned:
        bts.cells.check_state_on_all(state='online',
                                     timeout=60)


@pretty_log
def _save_config(bts: CloudBts,
                 output_dir_path: str) -> Dict[str, Dict[str, str]]:
    bts_config = {'cus': {}, 'dus': {}}
    config_directory = f'{output_dir_path}/scfs/{bts.name}'
    if not os.path.exists(config_directory):
        os.makedirs(config_directory)

    for cu in bts.cus:
        cu_scf_path = f'{config_directory}/{cu.name}.xml'
        cu.config.save(scf_path=cu_scf_path)
        bts_config['cus'][cu.name] = cu_scf_path

        for du in cu.dus:
            du_scf_path = f'{config_directory}/{du.name}.xml'
            du.config.save(scf_path=du_scf_path)
            bts_config['dus'][f'{du.name}'] = du_scf_path

    return bts_config


@pretty_log
def _check_detected_bts_components(bts: CloudBts, bts_config: Union[gNB, Enb], errors: ErrorHistory):
    log_info('Checking detected BTS components', to_console=True)
    error_type = 'BTS component detection'
    _check_detected_cus(bts, errors, error_type)
    _check_detected_dus(bts, bts_config, errors, error_type)
    _check_detected_rmods(bts, bts_config, errors, error_type)
    errors.check()


def _check_detected_cus(bts: CloudBts, errors: ErrorHistory, error_type: str):
    if len(bts.cus) != 1:
        errors.add(error_type=error_type,
                   error_msg=f'Number of detected CUs: {len(bts.cus)} is different than number specified in init: 1')


def _check_detected_dus(bts: CloudBts, bts_config: Union[gNB, Enb], errors: ErrorHistory, error_type: str):
    if len(bts.dus) != len(bts_config.dus):
        errors.add(error_type=error_type,
                   error_msg=f'Number of detected DUs: {len(bts.dus)} is different than number specified in init: {len(bts_config.dus)}')


def _check_detected_rmods(bts: CloudBts, bts_config: Union[gNB, Enb], errors: ErrorHistory, error_type: str):
    rmods_configs = []

    for du_config in bts_config.dus:
        if du_config.fhgws:
            for fhgw_config in du_config.fhgws:
                rmods_configs.extend(fhgw_config.rus)

        if du_config.rus:
            rmods_configs.extend(du_config.rus)

    if len(bts.rmods) != len(rmods_configs):
        errors.add(error_type=error_type,
                   error_msg=f'Number of detected RMODs: {len(bts.rmods)} is different than number specified in init: {len(rmods_configs)}')

    rmods_config_serial_numbers = sorted([rmod_config.serial_number for rmod_config in rmods_configs])
    rmods_detected_serial_numbers = sorted([rmod.serial_number for rmod in bts.rmods])

    if rmods_detected_serial_numbers != rmods_config_serial_numbers:
        errors.add(error_type=error_type,
                   error_msg=f'Detected RMODs serial numbers: {rmods_detected_serial_numbers} '
                             f'are different than specified in init: {rmods_config_serial_numbers}')

    for rmod_detected in bts.rmods:
        for rmod_config in rmods_configs:
            if rmod_detected.serial_number == rmod_config.serial_number and rmod_detected.product_code != rmod_config.product_code:
                errors.add(error_type=error_type,
                           error_msg=f'Detected RMOD with serial number: {rmod_detected.serial_number} has different product code: '
                                     f'{rmod_detected.product_code} than specified in init: {rmod_config.product_code}')


def _check_bts_components_state(bts: CloudBts, errors: ErrorHistory):
    for cu in bts.cus:
        try:
            cu.check_state(state='on_air')
        except UnexpectedState as exc:
            errors.add_from_exception(exc=exc)

    for du in bts.dus:
        try:
            du.check_state(state='on_air')
        except UnexpectedState as exc:
            errors.add_from_exception(exc=exc)

    for rmod in bts.rmods:
        try:
            rmod.check_state(state='online')
        except UnexpectedState as exc:
            errors.add_from_exception(exc=exc)

    for cell in bts.cells:
        try:
            cell.check_state(state='online')
        except UnexpectedState as exc:
            errors.add_from_exception(exc=exc)

    errors.check()


@pretty_log
def _collect_detected_alarms_and_stop_watching_them(bts_components, errors):
    for bts_component in bts_components:
        try:
            bts_component.alarms_watchdog.check_detected_alarms()
        except DisallowedAlarmsDetected as exc:
            errors.add_from_exception(exc=exc)
        finally:
            bts_component.alarms_watchdog.stop_watching_alarms()


@pretty_log
def _collect_detected_alarms_during_commissioning_and_stop_watching_them(alarms_watchdogs: List[alarms_watchdog],
                                                                         errors: ErrorHistory):
    for watchdog in alarms_watchdogs:
        try:
            watchdog.check_detected_alarms()
        except DisallowedAlarmsDetected as exc:
            errors.add_from_exception(exc=exc)
        finally:
            watchdog.stop_watching_alarms()
